@extends('layouts.app')
@section('title','Quiz Pemrograman Web')
@section('content')<div class="container py-5" style="max-width:900px"><div class="eyebrow mb-2">Evaluasi Mandiri</div><h1 class="section-title">Quiz Pemrograman Web</h1><p class="text-secondary">Jawaban diperiksa langsung di browser dan tidak disimpan.</p><div id="quiz" class="mt-4">@foreach($questions as $i=>$q)<div class="card-clean p-4 mb-4 quiz-question" data-answer="{{$q['answer']}}"><div class="small text-secondary mb-2">Soal {{$i+1}}</div><h2 class="h5 fw-bold">{{$q['question']}}</h2><div>@foreach($q['options'] as $j=>$option)<button class="quiz-option text-start w-100" data-index="{{$j}}">{{$option}}</button>@endforeach</div><div class="quiz-feedback small mt-3 d-none" data-explanation="{{$q['explanation']}}"></div></div>@endforeach</div><div class="card-clean p-4 text-center"><div class="text-secondary small">Skor</div><div class="display-6 fw-bold" id="score">0 / {{count($questions)}}</div><button id="resetQuiz" class="btn btn-outline-dark mt-2">Ulangi Quiz</button></div></div>@endsection
@push('scripts')<script>function calc(){let c=document.querySelectorAll('.quiz-question[data-done="1"] .quiz-option.correct').length;document.getElementById('score').textContent=c+' / {{count($questions)}}'}document.querySelectorAll('.quiz-option').forEach(b=>b.addEventListener('click',()=>{let q=b.closest('.quiz-question');if(q.dataset.done)return;q.dataset.done='1';let a=+q.dataset.answer,i=+b.dataset.index;b.classList.add(i===a?'correct':'wrong');q.querySelectorAll('.quiz-option')[a].classList.add('correct');let f=q.querySelector('.quiz-feedback');f.classList.remove('d-none');f.innerHTML=(i===a?'<span class="text-success fw-bold">Benar.</span> ':'<span class="text-danger fw-bold">Belum tepat.</span> ')+f.dataset.explanation;calc()}));document.getElementById('resetQuiz').onclick=()=>{document.querySelectorAll('.quiz-question').forEach(q=>{delete q.dataset.done;q.querySelectorAll('.quiz-option').forEach(b=>b.classList.remove('correct','wrong'));q.querySelector('.quiz-feedback').classList.add('d-none')});calc();scrollTo({top:0,behavior:'smooth'})}</script>@endpush